    trace(`signature idea (${seat}):`, `"${idea.idea}" ${tagOf(idea)}${idea.family ? ` [family: ${idea.family}]` : ''} — menu: ${menu.map((t) => t.id).join(', ') || 'EMPTY'}${pool.length > menu.length ? ` (+ shelf: ${pool.filter((t) => !menu.includes(t)).map((t) => t.id).join(', ')})` : ''}`);
